import { useEffect, useRef, useState } from "react";

function usePrefersReducedMotion(): boolean {
  const [reduced, setReduced] = useState<boolean>(() =>
    typeof window !== "undefined" && typeof window.matchMedia === "function"
      ? window.matchMedia("(prefers-reduced-motion: reduce)").matches
      : false
  );

  useEffect(() => {
    if (typeof window.matchMedia !== "function") return;
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    const onChange = (e: MediaQueryListEvent) => setReduced(e.matches);
    setReduced(mq.matches);
    mq.addEventListener("change", onChange);
    return () => mq.removeEventListener("change", onChange);
  }, []);

  return reduced;
}

function useInView<T extends Element>(threshold = 0.3) {
  const ref = useRef<T | null>(null);
  const [inView, setInView] = useState(false);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    if (typeof IntersectionObserver === "undefined") {
      setInView(true);
      return;
    }
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries.some((e) => e.isIntersecting)) {
          setInView(true);
          observer.disconnect();
        }
      },
      { threshold }
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, [threshold]);

  return { ref, inView };
}

type CardProps = {
  title: string;
  text: string;
  index: number;
  reduced: boolean;
};

function Card({ title, text, index, reduced }: CardProps) {
  const { ref, inView } = useInView<HTMLDivElement>(0.25);

  const style: React.CSSProperties = reduced
    ? {}
    : { transitionDelay: inView ? `${index * 150}ms` : "0ms" };

  const stateClasses = reduced
    ? "opacity-100"
    : inView
    ? "opacity-100 translate-y-0"
    : "opacity-0 translate-y-8";

  return (
    <div
      ref={ref}
      style={style}
      className={`rounded-2xl border border-slate-200 bg-white p-8 shadow-sm ${
        reduced ? "" : "transition-all duration-700 ease-out"
      } ${stateClasses}`}
    >
      <h3 className="text-xl font-semibold text-slate-900">{title}</h3>
      <p className="mt-2 text-slate-600">{text}</p>
    </div>
  );
}

function Counter({ target, reduced }: { target: number; reduced: boolean }) {
  const { ref, inView } = useInView<HTMLDivElement>(0.5);
  const [value, setValue] = useState(0);

  useEffect(() => {
    if (!inView) return;
    if (reduced) {
      setValue(target);
      return;
    }
    const duration = 2000;
    let raf = 0;
    let start: number | null = null;
    const tick = (now: number) => {
      if (start === null) start = now;
      const p = Math.min((now - start) / duration, 1);
      const eased = 1 - Math.pow(1 - p, 3);
      setValue(Math.round(target * eased));
      if (p < 1) raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [inView, reduced, target]);

  return (
    <div ref={ref} className="text-center">
      <div
        className="text-6xl font-extrabold tabular-nums text-slate-900 sm:text-7xl"
        aria-label={`${target.toLocaleString("es-AR")} más usuarios`}
      >
        <span aria-hidden="true">
          {value.toLocaleString("es-AR")}+
        </span>
      </div>
      <p className="mt-2 text-lg text-slate-600">usuarios</p>
    </div>
  );
}

export default function App() {
  const reduced = usePrefersReducedMotion();

  const cards = [
    { title: "Rápido", text: "Carga en un instante, sin esperas." },
    { title: "Simple", text: "Todo es claro e intuitivo desde el primer minuto." },
    { title: "Abierto", text: "Código abierto y pensado para la comunidad." },
  ];

  return (
    <div className="min-h-screen bg-slate-50 font-sans text-slate-900">
      <style>{`
        @keyframes nimbus-gradient {
          0% { background-position: 0% 50%; }
          50% { background-position: 100% 50%; }
          100% { background-position: 0% 50%; }
        }
        .nimbus-bg {
          background-size: 300% 300%;
          animation: nimbus-gradient 20s ease infinite;
        }
        @media (prefers-reduced-motion: reduce) {
          .nimbus-bg { animation: none; }
        }
      `}</style>

      <header className="relative flex min-h-screen items-center justify-center overflow-hidden">
        <div
          aria-hidden="true"
          className="nimbus-bg absolute inset-0 bg-gradient-to-br from-indigo-500 via-sky-400 to-fuchsia-500"
        />
        <div className="relative z-10 px-6 text-center text-white">
          <h1 className="text-6xl font-extrabold tracking-tight sm:text-8xl">
            Nimbus
          </h1>
          <p className="mx-auto mt-6 max-w-xl text-lg text-white/90 sm:text-2xl">
            La forma más ligera de llevar tus ideas a la nube.
          </p>
          <button
            type="button"
            className={`mt-10 rounded-full bg-white px-8 py-3 text-lg font-semibold text-indigo-600 shadow-lg focus:outline-none focus-visible:ring-4 focus-visible:ring-white/60 ${
              reduced
                ? ""
                : "transition-transform duration-300 ease-out hover:scale-110"
            }`}
          >
            Empezar
          </button>
        </div>
      </header>

      <main>
        <section className="mx-auto max-w-5xl px-6 py-24">
          <div className="grid gap-6 md:grid-cols-3">
            {cards.map((c, i) => (
              <Card
                key={c.title}
                title={c.title}
                text={c.text}
                index={i}
                reduced={reduced}
              />
            ))}
          </div>
        </section>

        <section className="px-6 pb-32">
          <Counter target={12000} reduced={reduced} />
        </section>
      </main>
    </div>
  );
}

