    let interval = 0;

    const cleanup = () => {
      observer?.disconnect();
      window.clearInterval(interval);
      window.removeEventListener("scroll", check);
      window.removeEventListener("resize", check);
    };

    const reveal = () => {
      setInView(true);
      cleanup();
    };

    // Comprobación manual por geometría (respaldo del IntersectionObserver)
    function check() {
      const rect = el!.getBoundingClientRect();
      const vh = window.innerHeight || document.documentElement.clientHeight;
      if (rect.top < vh && rect.bottom > 0) reveal();
    }

    if (typeof IntersectionObserver !== "undefined") {
      observer = new IntersectionObserver(
        (entries) => {
          if (entries.some((e) => e.isIntersecting)) reveal();
        },
        { threshold }
      );
      observer.observe(el);
    }

    window.addEventListener("scroll", check, { passive: true });
    window.addEventListener("resize", check);
    interval = window.setInterval(check, 300);
    check();

    return cleanup;
  }, [threshold, inView]);

  return { ref, inView };
}

function Reveal({
  children,
  delay = 0,
  reduced,
  className = "",
}: {
  children: ReactNode;
  delay?: number;
  reduced: boolean;
  className?: string;
}) {
  const { ref, inView } = useInView<HTMLDivElement>(0.15);
  const visible = inView || reduced;

  return (
    <div
      ref={ref}
      className={`${className} ${
        reduced ? "" : "transition-all duration-700 ease-out"
      } ${visible ? "opacity-100 translate-y-0" : "opacity-0 translate-y-8"}`}
      style={{ transitionDelay: reduced ? "0ms" : `${delay}ms` }}
    >
      {children}
    </div>
  );
}

function Counter({
  target,
  reduced,
  duration = 1800,
}: {
  target: number;
  reduced: boolean;
  duration?: number;
}) {
  const { ref, inView } = useInView<HTMLDivElement>(0);
  const [value, setValue] = useState(0);

  useEffect(() => {
    if (!inView) return;
    if (reduced) {
      setValue(target);
      return;
    }
    let raf = 0;
    const start = Date.now();
    const tick = () => {
      const p = Math.min((Date.now() - start) / duration, 1);
      const eased = 1 - Math.pow(1 - p, 3);
      setValue(Math.round(target * eased));
      if (p < 1) raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    // Garantiza el valor final aunque los frames se pausen
    const done = window.setTimeout(() => setValue(target), duration + 50);
    return () => {
      cancelAnimationFrame(raf);
      window.clearTimeout(done);
    };
  }, [inView, reduced, target, duration]);

  return <div ref={ref}>{value.toLocaleString("es-AR")}+</div>;
}

